const STREAMS = {
  en: { cardboard: "Cardboard", paper: "Paper", plastic_film: "Plastic film", mixed_plastic: "Mixed plastic", mixed_waste: "Mixed waste", biowaste: "Biowaste" },
  fi: { cardboard: "Kartonki", paper: "Paperi", plastic_film: "Muovikalvo", mixed_plastic: "Sekamuovi", mixed_waste: "Sekajäte", biowaste: "Biojäte" },
};

const SECTORS = {
  en: { grocery_retail: "Grocery retail", nonfood_retail: "Non-food retail", manufacturing: "Manufacturing", hospitality_hotel: "Hotels & hospitality",
        logistics_warehouse: "Logistics", food_processing: "Food processing", office_services: "Offices", shopping_center: "Shopping centre" },
  fi: { grocery_retail: "Päivittäistavarakauppa", nonfood_retail: "Erikoiskauppa", manufacturing: "Teollisuus", hospitality_hotel: "Hotellit ja ravintolat",
        logistics_warehouse: "Logistiikka", food_processing: "Elintarviketeollisuus", office_services: "Toimistot", shopping_center: "Kauppakeskus" },
};

let lang = "fi";
try { lang = localStorage.getItem("ep.lang") || "fi"; } catch { /* storage blocked */ }
if (!STRINGS[lang]) lang = "fi";

export const getLang = () => lang;
export function setLang(l) {
  lang = STRINGS[l] ? l : "en";
  try { localStorage.setItem("ep.lang", lang); } catch { /* storage blocked */ }
  document.documentElement.lang = lang;
}

/** Feature modules register their own strings (e.g. js/sensor/strings.js); later keys win. */
export function addStrings(table) {
  for (const l of Object.keys(table)) if (STRINGS[l]) STRINGS[l] = { ...STRINGS[l], ...table[l] };
}

export function t(key, params = {}) {
  const s = STRINGS[lang][key] ?? STRINGS.en[key] ?? key;
  return s.replace(/\{(\w+)\}/g, (_, k) => String(params[k] ?? `{${k}}`));
}
export const stream = (s) => STREAMS[lang][s] || s;
export const sector = (s) => SECTORS[lang][s] || s;

const locale = () => (lang === "fi" ? "fi-FI" : "en-GB");
export const fmt = (v, digits = 0) =>
  v == null ? "–" : new Intl.NumberFormat(locale(), { maximumFractionDigits: digits, minimumFractionDigits: digits }).format(v);
export const eur = (v) =>
  v == null ? "–" : new Intl.NumberFormat(locale(), { style: "currency", currency: "EUR", maximumFractionDigits: 0 }).format(v);
export const month = (ym) => new Intl.DateTimeFormat(locale(), { month: "short" }).format(new Date(`${ym}-01T00:00:00`));
export const date = (iso) => new Intl.DateTimeFormat(locale(), { day: "numeric", month: "short", year: "numeric" }).format(new Date(iso));

export function applyStatic(root = document) {
  root.querySelectorAll("[data-i18n]").forEach((el) => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll("[data-i18n-ph]").forEach((el) => { el.placeholder = t(el.dataset.i18nPh); });
  root.querySelectorAll("[data-i18n-aria]").forEach((el) => { const v = t(el.dataset.i18nAria); el.setAttribute("aria-label", v); el.title = v; });
}
